-- Radarr-style size limits per quality on the shipped video profiles: a release starved below the minimum or bloated above the maximum is refused; one whose length is not known is not.
UPDATE quality_profile SET rules_json = json_patch(rules_json, '{"require":{"size":"reject_outside_range"},"targets":{"overall_bitrate":[{"when":{"resolution":"2160p"},"min":"40MB/min","ideal":"200MB/min","max":"800MB/min"},{"when":{"resolution":"1080p"},"min":"10MB/min","ideal":"60MB/min","max":"260MB/min"},{"when":{"resolution":"720p"},"min":"5MB/min","ideal":"30MB/min","max":"130MB/min"},{"when":{"resolution":"576p"},"min":"3MB/min","ideal":"15MB/min","max":"80MB/min"},{"when":{"resolution":"480p"},"min":"2MB/min","ideal":"12MB/min","max":"60MB/min"}]}}') WHERE id = 4;
